using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 renamed the discriminator property from "Discriminator" to "$type".
            // Existing 500K documents use "Discriminator", so we must keep the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed the id format from "Product|<key>" to just "<key>".
            // Existing documents use "Product|<id>", so we generate ids in the legacy format.
            entity.Property("__id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        base.OnConfiguring(optionsBuilder);
    }
}

/// <summary>
/// Reproduces the EF Core 8 id format: "EntityTypeName|KeyValue".
/// Required so EF Core 9 can read/write existing Cosmos documents.
/// </summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    protected override string GenerateNonNullValue(EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var pk = entry.Metadata.FindPrimaryKey()!;
        var keyValues = string.Join("|",
            pk.Properties.Select(p => entry.Property(p.Name).CurrentValue));
        return $"{entityType}|{keyValues}";
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

